function cccDecodeImage(bytes, src){
  try{
    var m=src.match(/encrypt\/(\d+)\/2/);
    if(!m)return bytes;
    var pid=m[1];
    var keyResp=java.ajax('https://api.creative-comic.tw/book/chapter/image/'+pid);
    var b64key=JSON.parse(keyResp).data.key;
    var dig=java.digestHex('freeforccc2020reading','SHA-512');
    var kBytes=java.hexDecodeToByteArray(dig.substring(0,64));
    var ivBytes=java.hexDecodeToByteArray(dig.substring(30,62));
    var plain=java.createSymmetricCrypto('AES/CBC/PKCS5Padding',kBytes,ivBytes).decrypt(java.base64DecodeToByteArray(b64key));
    var ks=java.bytesToStr(plain,'UTF-8').split(':');
    var imgKey=java.hexDecodeToByteArray(ks[0]);
    var imgIv=java.hexDecodeToByteArray(ks[1]);
    var dec=java.createSymmetricCrypto('AES/CBC/PKCS5Padding',imgKey,imgIv).decrypt(bytes);
    var s=java.bytesToStr(dec,'UTF-8');
    var i=s.lastIndexOf(',');
    if(i<0)return bytes;
    return java.base64DecodeToByteArray(s.substring(i+1).trim());
  }catch(e){return bytes;}
}

ruleSearch.bookList:
@js:(function(){
var d=JSON.parse(result).data.data;var out=[];
for(var i=0;i<d.length;i++){
  var c=d[i];var au=[];
  if(c.author){for(var j=0;j<c.author.length;j++)au.push(c.author[j].name);}
  out.push({name:c.name,author:au.join('/'),coverUrl:c.image1||c.image2||c.image3,bookUrl:'https://api.creative-comic.tw/book/'+c.id+'/info',intro:c.brief||''});
}
return out;})()

